+export const ZimmProductPrice = ({ currentPrice, originalPrice, isLoading, variant: variantProp = 'default' }: ZimmProductPriceProps) => {
+  // During loading, always use the sale variant so the flex row + two-span structure is rendered
+  // (invisible) — this preserves the exact Was/Now dimensions while the fetch is in flight.
+  const variant = isLoading ? 'sale' : (originalPrice ? 'sale' : variantProp);
