104	    const undeclared = [...new Set(recipe.read)].filter((part) => !recipe.declared.includes(part));
105	    expect(undeclared, `${recipe.componentFile} reads parts absent from ${recipe.recipeFile}`).toEqual([]);
106	  });
107	
108	  // Vacuity guard. A suite built by walking the filesystem passes trivially when the walk
109	  // returns nothing — a moved directory or a renamed suffix would turn this file into a
110	  // no-op that still reports green. Mirrors recipeGuards.test.ts's own self-test.
111	  test('the walk actually collected something', () => {
