113	    expect(recipes.length).toBeGreaterThan(0);
114	    expect(recipes.every((recipe) => recipe.declared.length > 0)).toBe(true);
115	    expect(recipes.some((recipe) => recipe.read.length > 0)).toBe(true);
116	  });
117	});

