const info = selectPdpProductInfo(headerProduct ?? { name }, priceData, currency ?? '', formatPrice);

return (
  <VStack mr={4} spacing={2} align="flex-start" marginBottom={[4, 4, 4, 0, 0]}>
    {headerCategory && (
      <Skeleton isLoaded={headerCategory} minWidth={64}>
        <Breadcrumb categories={headerCategory} />
      </Skeleton>
    )}

    {/*
     * `minHeight` reserves the name's line box, so the title does not shove the page down
     * when it resolves. SFCC's `Skeleton` baseStyle sets only `borderRadius` and `opacity`,
     * so an empty one measures 0px; the base header avoids that by interpolating the name
     * into a template, which stringifies `undefined` to "undefined" and is therefore always
     * title-height. The value is the name's own line-height: `ZimmProductName` renders at
     * `textStyle: 'heading3'` (declared in its recipe, not as a prop), whose `lineHeight` is
     * `lineHeights['2xs']` (1.125rem / 18px) —
     * the same entry `--zimm-font-lineheight-2xs` is derived from.
     *
     * This reserves ONE line, matching base. A name that wraps still shifts by ~18px, and
     * wrapping is a real case — the design caps the name at 180px inside a 218px column and
